<template><section aria-label="文本处理工具箱"><p class="tool-note">逐行去重保留首次出现的原文；批量替换按普通文字匹配，不使用正则。</p><div class="tool-actions"><button v-for="item in actions" :key="item[0]" type="button" @click="run(item[0])">{{ item[1] }}</button></div><div class="tool-actions"><label>查找<input v-model="find" aria-label="文本查找内容" /></label><label>替换为<input v-model="replacement" aria-label="文本替换内容" /></label><button type="button" :disabled="!find" @click="run('replace')">全部替换</button></div><div class="tool-two-column"><label class="tool-label">原始文本<textarea v-model="input" aria-label="原始文本" spellcheck="false"></textarea><small>{{ stats.characters }} 字符 · {{ stats.nonWhitespace }} 非空白字符 · {{ stats.lines }} 行 · {{ stats.bytes }} UTF-8 字节</small></label><label class="tool-label">处理结果<textarea v-model="output" aria-label="文本处理结果" spellcheck="false"></textarea><small>结果可继续编辑，点击“结果作为输入”进行下一步处理。</small></label></div><div class="tool-actions"><button type="button" :disabled="!output" @click="input = output">结果作为输入</button><button type="button" :disabled="!output" @click="copy">复制结果</button><button type="button" :disabled="!output" @click="download">下载 TXT</button><button type="button" @click="input = ''; output = ''; message = ''">清空文本</button></div><p role="status">{{ message }}</p></section></template>
<script>
import { textStats, processText, downloadBlob } from '../../utils/utility-tools.mjs';
export default { name: 'TextTool', data: () => ({ input: '', output: '', find: '', replacement: '', message: '', actions: [['dedupe','逐行去重'],['no-empty','去除空行'],['trim-lines','去除行首尾空格'],['sort','升序排列'],['reverse-sort','降序排列'],['upper','转大写'],['lower','转小写']] }), computed: { stats() { return textStats(this.input); } }, methods: { run(action) { try { this.output = processText(this.input, action, this); this.message = '处理完成'; } catch (e) { this.message = e.message; } }, async copy() { try { await navigator.clipboard.writeText(this.output); this.message = '已复制文本结果'; } catch { this.message = '复制未完成，请选中结果手动复制'; } }, download() { downloadBlob(new Blob([this.output], { type: 'text/plain;charset=utf-8' }), '01-text.txt'); } } };
</script>
